 3	    static int count(int[] coins, int sum) {
 4	        validateInputs(coins, sum);
 5	
 6	        int[] waysBySum = new int[sum + 1];
 7	        waysBySum[0] = 1;
 8	
 9	        // Process each coin once so combinations are counted without regard to order.
10	        for (int coin : coins) {
11	            for (int currentSum = coin; currentSum <= sum; currentSum++) {
12	                waysBySum[currentSum] += waysBySum[currentSum - coin];
13	            }
14	        }
15	
16	        return waysBySum[sum];
17	    }
18	
19	    private static void validateInputs(int[] coins, int sum) {
20	        if (coins == null) {
21	            throw new IllegalArgumentException("coins must not be null");
22	        }
23	        if (sum < 0) {
24	            throw new IllegalArgumentException("sum must not be negative");
25	        }
26	        for (int coin : coins) {
27	            if (coin <= 0) {
28	                throw new IllegalArgumentException("coin values must be positive");
29	            }
30	        }
31	    }
